import sys
import bisect
NN = 27
pw = [[1] * NN for i in range(NN)]
(fac, cnt, adj, sz) = ([1] * NN, [0] * NN, [[] for i in range(NN)], [0] * NN)

def dfs(val, num, ed):
	if val == 0 and num > 0:
		return 0
	if val == 0:
		if ed != 1:
			return 0
		(N, M, v) = (0, 1, 1)
		for i in range(10):
			N += cnt[i]
			M *= fac[cnt[i]]
			v *= pw[i][cnt[i]]
		NUM = fac[N] // M
		adj[N].append([v, NUM])
		return 0
	if pw[val][num] < ed:
		return 0
	for i in range(num + 1):
		v = pw[val][i]
		cnt[val] = i
		dfs(val - 1, num - i, (ed + v - 1) // v)

def CLC(u):
	adj[u] = sorted(adj[u])
	ed = 0
	for i in range(1, len(adj[u])):
		if adj[u][i][0] == adj[u][ed][0]:
			adj[u][ed][1] += adj[u][i][1]
		else:
			adj[u][ed + 1] = adj[u][i]
			ed += 1
	sz[u] = ed + 1
	for i in range(ed - 1, -1, -1):
		adj[u][i][1] += adj[u][i + 1][1]
a = [0] * NN

def seg(u, V):
	if u == 0:
		if V < 2:
			return 1
		else:
			return 0
	it = bisect.bisect_left(adj[u], [V, 0], lo=0, hi=sz[u])
	if it == sz[u]:
		return 0
	return adj[u][it][1]

def calc(n):
	L = 0
	while n > 0:
		a[L] = n % 10
		L += 1
		n //= 10
	ans = 0
	for i in range(1, L):
		ans += seg(i, fac[i])
	V = fac[L]
	for i in range(L - 1, -1, -1):
		for j in range(1, a[i]):
			ans += seg(i, (V + j - 1) // j)
		if a[i] == 0:
			break
		V = (V + a[i] - 1) // a[i]
		if i == 0:
			if V == 1:
				ans += 1
	return ans
for i in range(NN):
	for j in range(1, NN):
		pw[i][j] = pw[i][j - 1] * i
for i in range(1, NN):
	fac[i] = fac[i - 1] * i
for i in range(1, NN):
	CNT = 0
	if i > 10:
		dfs(9, i, fac[i])
	else:
		dfs(9, i, 1)
	CLC(i)
t = int(input())
for i in range(t):
	n = int(input())
	n = min(n, 10 ** 22 - 1)
	print(min(n, calc(n)))
